fn bin_search(a: &[i32], k: i32) -> bool {
    // Precondition: a is a sorted slice of integers
    // Requires: a.len() > 0 implies a[0] <= a[1] <= ... <= a[a.len() - 1]
    // Ensures: returns true if k is found in a, otherwise false
    // Decreases: right - left
    // Invariant: 0 <= left <= right < a.len() as isize
    // Invariant: for all i in left..=right, a[i as usize] is sorted
    // Invariant: if k is in a, then there exists an index i such that a[i] == k

    let mut left = 0;
    let mut right = a.len() as isize - 1; // Use isize for indexing

    while left <= right {
        let mid = (left + right) / 2; // Calculate the middle index
        // Assert that mid is within bounds
        assert!(0 <= mid && mid < a.len() as isize);
        
        if a[mid as usize] == k {
            return true; // Target found
        } else if a[mid as usize] < k {
            left = mid + 1; // Search in the right half
        } else {
            right = mid - 1; // Search in the left half
        }
    }
    false // Target not found
}

